/**
 * Governance seed (docs/seed-data.md — M2 share: organization members, teams,
 * team hierarchy, team grant).
 *
 * Every write is keyed by business identity and insert-if-absent, so running
 * the seed again (every application start) never overwrites data a user
 * produced. The organization and the organization repositories use the same
 * business keys as the M3 repository seed (`seed/repos.js`): both seeds may run
 * in either order and the result is identical.
 */
import { registerSeed } from './index.js';

export const SEED_GOVERNANCE_ORG = { name: 'acme-demo', displayName: 'Acme Demo' };
export const SEED_GOVERNANCE_ORG_REPOS = {
  public: { name: 'org-handbook', visibility: 'public' },
  private: { name: 'org-private', visibility: 'private' },
};
export const SEED_GOVERNANCE_TEAMS = [
  { name: 'frontend-team', description: 'Frontend development team', parent: null },
  { name: 'platform-team', description: 'Platform and infrastructure team', parent: null },
  { name: 'frontend-child', description: 'Child team for hierarchy demonstrations', parent: 'platform-team' },
];

export function seedGovernance(db) {
  const userByUsername = (username) =>
    db.prepare('SELECT * FROM users WHERE username = ?').get(username);

  const alice = userByUsername('alice-dev');
  const bob = userByUsername('bob-reviewer');
  if (!alice || !bob) {
    throw new Error('seed(governance): accounts "alice-dev"/"bob-reviewer" must exist before this seed runs');
  }

  // Organization + memberships (same business keys as the M3 repository seed;
  // existing roles are never overwritten).
  db.prepare(
    'INSERT INTO organizations (name, display_name) VALUES (?, ?) ON CONFLICT DO NOTHING',
  ).run(SEED_GOVERNANCE_ORG.name, SEED_GOVERNANCE_ORG.displayName);
  const org = db.prepare('SELECT * FROM organizations WHERE name = ?').get(SEED_GOVERNANCE_ORG.name);

  const ensureOrgMember = db.prepare('INSERT OR IGNORE INTO org_members (org_id, user_id, role) VALUES (?, ?, ?)');
  ensureOrgMember.run(org.id, alice.id, 'owner');
  ensureOrgMember.run(org.id, bob.id, 'member');

  // Organization repositories (one public, one private) — insert-if-absent so
  // the M3 seed and this seed can create/see the same rows in either order.
  for (const repo of Object.values(SEED_GOVERNANCE_ORG_REPOS)) {
    const existing = db
      .prepare('SELECT id FROM repos WHERE owner_org_id = ? AND name = ?')
      .get(org.id, repo.name);
    if (!existing) {
      db.prepare(
        `INSERT INTO repos (owner_org_id, name, description, visibility) VALUES (?, ?, ?, ?)`,
      ).run(org.id, repo.name, `Acme Demo ${repo.visibility} demonstration repository`, repo.visibility);
    }
  }

  // Teams + hierarchy (REQ-2-2-2 cycle scenario: frontend-child under platform-team).
  const teamIds = new Map();
  for (const team of SEED_GOVERNANCE_TEAMS) {
    db.prepare(
      'INSERT INTO teams (org_id, name, description) VALUES (?, ?, ?) ON CONFLICT DO NOTHING',
    ).run(org.id, team.name, team.description);
    const row = db.prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?').get(org.id, team.name);
    teamIds.set(team.name, row.id);
  }
  const setParent = db.prepare('UPDATE teams SET parent_team_id = ? WHERE id = ? AND parent_team_id IS NULL');
  for (const team of SEED_GOVERNANCE_TEAMS) {
    if (team.parent) {
      // Only fills an unset parent, so a parent changed through the UI survives.
      setParent.run(teamIds.get(team.parent), teamIds.get(team.name));
    }
  }

  // Direct team membership (REQ-2-2 scenarios) — never removed by re-seeding.
  db.prepare('INSERT OR IGNORE INTO team_members (team_id, user_id) VALUES (?, ?)').run(
    teamIds.get('frontend-team'),
    bob.id,
  );

  // Existing Write grant for the REQ-2-3 role-replacement scenario.
  const handbook = db
    .prepare('SELECT id FROM repos WHERE owner_org_id = ? AND name = ?')
    .get(org.id, SEED_GOVERNANCE_ORG_REPOS.public.name);
  if (handbook) {
    db.prepare(
      `INSERT OR IGNORE INTO repo_grants (repo_id, subject_team_id, role) VALUES (?, ?, 'write')`,
    ).run(handbook.id, teamIds.get('frontend-team'));
  }
}

registerSeed('governance', seedGovernance);

/**
 * REQ-2 acceptance scenarios (docs/task-packets/m2-issue-4.md):
 * browse organization repositories, create organization, teams, team members &
 * hierarchy, direct member add/remove, repository grants. Permission tiers are
 * asserted as absent controls AND rejected APIs; persistence is asserted with
 * reloads. Write objects use `pw-*` unique suffixes (docs/seed-data.md).
 *
 * The "Access denied" assertions (REQ-2-2-3) depend on the root-ruled follow-up
 * PR #14 (signed-in users see "Access denied" on inaccessible repositories);
 * they run against develop only after #14 lands — see PR #13.
 */
import { expect, test, type Page } from '@playwright/test';
import { errors as errorCopy, org as orgCopy, auth as authCopy } from '../frontend/src/contracts/copy';
import { registerAccount, SEED_ACCOUNT, signIn, uniqueToken } from './helpers';

const PASSWORD = 'Valid-password-123!';

async function openOrgRepositories(page: Page, org = 'acme-demo') {
  await page.goto(`/orgs/${org}`);
  await expect(page.getByRole('heading', { level: 1, name: org })).toBeVisible();
}

test.describe('REQ-2-1-1 browse organization repositories', () => {
  test('visitor sees only public repositories, filter works as-you-type, click opens the overview', async ({
    page,
  }) => {
    await openOrgRepositories(page);

    // Tab semantics: Repositories/People/Teams are links.
    await expect(page.getByRole('link', { name: orgCopy.repositories })).toBeVisible();
    await expect(page.getByRole('link', { name: orgCopy.people })).toBeVisible();
    await expect(page.getByRole('link', { name: orgCopy.teams })).toBeVisible();

    // The private repository is never rendered for a visitor.
    await expect(page.getByRole('link', { name: 'org-private' })).toHaveCount(0);

    // As-you-type filtering, no submit.
    const filter = page.getByRole('textbox', { name: orgCopy.findRepository });
    await filter.fill('org-handbook');
    await expect(page.getByRole('link', { name: 'org-handbook' })).toBeVisible();
    await filter.fill('org-private');
    await expect(page.getByText(errorCopy.notFound, { exact: false })).toHaveCount(0);
    await expect(page.getByText('No results')).toBeVisible();

    // Visibility filter (registered UI decision): Private shows nothing to a visitor.
    await page.getByRole('combobox', { name: orgCopy.visibilityFilter }).selectOption('private');
    await expect(page.getByText('No results')).toBeVisible();
    await page.getByRole('combobox', { name: orgCopy.visibilityFilter }).selectOption('public');
    await filter.fill('');
    await expect(page.getByRole('link', { name: 'org-handbook' })).toBeVisible();

    // Clicking the result opens the repository overview "org/name" (M3 page).
    await page.getByRole('link', { name: 'org-handbook' }).click();
    await expect(page).toHaveURL(/\/acme-demo\/org-handbook$/);
    await expect(page.getByRole('heading', { level: 1, name: 'acme-demo/org-handbook' })).toBeVisible();

    // Back to the organization page: the public result is still available.
    await page.goBack();
    await expect(page.getByRole('heading', { level: 1, name: org })).toBeVisible();

    // Refresh persistence: the private repository stays hidden.
    await page.reload();
    await expect(page.getByRole('link', { name: 'org-private' })).toHaveCount(0);
  });

  test('an ordinary member sees only public repositories; the Owner sees both', async ({ browser }) => {
    const member = await (await browser.newContext()).newPage();
    await signIn(member, 'bob-reviewer', PASSWORD);
    await openOrgRepositories(member);
    await expect(member.getByRole('link', { name: 'org-handbook' })).toBeVisible();
    await expect(member.getByRole('link', { name: 'org-private' })).toHaveCount(0);

    const owner = await (await browser.newContext()).newPage();
    await signIn(owner, SEED_ACCOUNT.username, PASSWORD);
    await openOrgRepositories(owner, 'acme-demo');
    await expect(owner.getByRole('link', { name: 'org-handbook' })).toBeVisible();
    await expect(owner.getByRole('link', { name: 'org-private' })).toBeVisible();
  });
});

test.describe('REQ-2-1-2 create organization', () => {
  test('creates an organization through the account menu and lands on its overview', async ({ page }) => {
    const account = await registerAccount(page);
    await signIn(page, account.username, account.password);
    await page.getByRole('button', { name: authCopy.accountMenu }).click();
    await page.getByRole('link', { name: authCopy.yourOrganizations }).click();
    await expect(page.getByRole('heading', { name: authCopy.yourOrganizations })).toBeVisible();

    const orgName = uniqueToken('pw-org').slice(0, 39);
    await page.getByRole('link', { name: orgCopy.newOrganization }).click();
    await page.getByLabel(orgCopy.organizationName).fill(orgName);
    await page.getByLabel(orgCopy.displayName).fill('PW Mobile Guild');
    await page.getByRole('button', { name: orgCopy.createOrganization }).click();

    // Redirect to the new overview, heading = identifier.
    await expect(page).toHaveURL(new RegExp(`/orgs/${orgName}$`));
    await expect(page.getByRole('heading', { level: 1, name: orgName })).toBeVisible();

    // Appears in "Your organizations" and survives reload.
    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: orgName })).toBeVisible();
    await page.getByRole('button', { name: authCopy.accountMenu }).click();
    await page.getByRole('link', { name: authCopy.yourOrganizations }).click();
    await expect(page.getByRole('link', { name: orgName })).toBeVisible();
  });

  test('duplicate name + missing display name are reported together; malformed name shows the format error', async ({
    page,
  }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/orgs/new');

    await page.getByLabel(orgCopy.organizationName).fill('acme-demo');
    await page.getByLabel(orgCopy.displayName).fill('   ');
    await page.getByRole('button', { name: orgCopy.createOrganization }).click();
    await expect(page.getByText(errorCopy.orgNameExists)).toBeVisible();
    await expect(page.getByText(errorCopy.displayNameRequired)).toBeVisible();
    // No navigation to the existing organization.
    await expect(page).toHaveURL(/\/orgs\/new$/);

    await page.getByLabel(orgCopy.organizationName).fill('-invalid-organization');
    await page.getByRole('button', { name: orgCopy.createOrganization }).click();
    await expect(page.getByText(errorCopy.orgNameFormatInvalid)).toBeVisible();
    await expect(page).toHaveURL(/\/orgs\/new$/);
  });
});

test.describe('REQ-2-2-1 create team', () => {
  test('Owner creates a team and lands on its page', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/orgs/acme-demo/teams');
    await page.getByRole('link', { name: orgCopy.newTeam }).click();

    const teamName = uniqueToken('pw-team');
    await page.getByLabel(orgCopy.teamName).fill(teamName);
    await page.getByRole('button', { name: orgCopy.createTeam }).click();
    await expect(page).toHaveURL(new RegExp(`/orgs/acme-demo/teams/${teamName}$`));
    await expect(page.getByRole('heading', { name: `acme-demo/${teamName}` })).toBeVisible();

    await page.reload();
    await expect(page.getByRole('heading', { name: `acme-demo/${teamName}` })).toBeVisible();
    await page.getByRole('link', { name: orgCopy.teams, exact: true }).first().click();
    await expect(page.getByRole('link', { name: teamName })).toBeVisible();
  });

  test('malformed team name shows the format error and creates nothing', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/orgs/acme-demo/teams/new');
    await page.getByLabel(orgCopy.teamName).fill('-bad-');
    await page.getByRole('button', { name: orgCopy.createTeam }).click();
    await expect(page.getByText(errorCopy.teamNameFormatInvalid)).toBeVisible();
    await expect(page).toHaveURL(/\/orgs\/acme-demo\/teams\/new$/);
  });
});

test.describe('REQ-2-2-2 team members and hierarchy', () => {
  test('Owner adds and removes a team member immediately', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    // carol must be an organization member first (People flow, REQ-2-2-3).
    await page.goto('/orgs/acme-demo/people');
    await page.getByRole('button', { name: orgCopy.addMember }).click();
    await page.getByLabel(authCopy.usernameOrEmail).fill('carol-writer');
    await page.getByRole('form').getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByText('carol-writer')).toBeVisible();

    await page.goto('/orgs/acme-demo/teams/frontend-team');
    await expect(page.getByRole('heading', { name: 'acme-demo/frontend-team' })).toBeVisible();
    await expect(page.getByRole('link', { name: orgCopy.members })).toBeVisible();
    await expect(page.getByRole('link', { name: authCopy.settings })).toBeVisible();

    // Only one actionable "Add member" while the form is open (trigger hidden).
    await page.getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByRole('button', { name: orgCopy.addMember })).toHaveCount(1);
    await page.getByLabel(authCopy.username).fill('carol-writer');
    await page.getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByText('carol-writer')).toBeVisible();

    // Immediate removal, no confirmation; persists after reload.
    await page.getByRole('button', { name: orgCopy.removeTeamMember('carol-writer') }).click();
    await expect(page.getByText('carol-writer')).toHaveCount(0);
    await page.reload();
    await expect(page.getByText('carol-writer')).toHaveCount(0);
  });

  test('setting a valid parent saves; a cyclic selection is rejected and keeps the original', async ({
    page,
  }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);

    // Valid parent for frontend-team.
    await page.goto('/orgs/acme-demo/teams/frontend-team/settings');
    await page.getByRole('combobox', { name: orgCopy.parentTeam }).selectOption('platform-team');
    await page.getByRole('button', { name: orgCopy.save }).click();
    await expect(page.getByText('Saved')).toBeVisible();
    await page.reload();
    await expect(page.getByRole('combobox', { name: orgCopy.parentTeam })).toHaveValue('platform-team');

    // Cycle: platform-team's descendant frontend-child cannot become its parent.
    await page.goto('/orgs/acme-demo/teams/platform-team/settings');
    await page.getByRole('combobox', { name: orgCopy.parentTeam }).selectOption('frontend-child');
    await page.getByRole('button', { name: orgCopy.save }).click();
    await expect(page.getByText(errorCopy.cyclicTeamHierarchy)).toBeVisible();

    // The original parent (none) is kept after reload.
    await page.reload();
    await expect(page.getByRole('combobox', { name: orgCopy.parentTeam })).toHaveValue('');
  });

  test('a non-Owner has no team management controls', async ({ page }) => {
    await signIn(page, 'bob-reviewer', PASSWORD);
    await page.goto('/orgs/acme-demo/teams/frontend-team');
    await expect(page.getByRole('button', { name: orgCopy.addMember })).toHaveCount(0);
    await expect(page.getByRole('button', { name: orgCopy.removeTeamMember('bob-reviewer') })).toHaveCount(0);
  });
});

test.describe('REQ-2-2-3 direct member management', () => {
  test('Owner adds a member with the Role combobox; errors keep the form open', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/orgs/acme-demo/people');
    await page.getByRole('button', { name: orgCopy.addMember }).click();

    // The opening button remains present; the submission button follows it.
    const buttons = page.getByRole('button', { name: orgCopy.addMember });
    await expect(buttons).toHaveCount(2);
    const roleSelect = page.getByLabel(orgCopy.role, { exact: true });
    await expect(roleSelect).toHaveValue('member');
    await expect(roleSelect.getByRole('option', { name: orgCopy.roleMember })).toBeAttached();
    await expect(roleSelect.getByRole('option', { name: orgCopy.roleOwner })).toBeAttached();

    // Unknown account error, form stays open.
    await page.getByLabel(authCopy.usernameOrEmail).fill('unknown-reviewer');
    await page.getByRole('form').getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByText(errorCopy.accountNotFound)).toBeVisible();

    // Duplicate error.
    await page.getByLabel(authCopy.usernameOrEmail).fill('bob-reviewer');
    await page.getByRole('form').getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByText(errorCopy.accountAlreadyMember)).toBeVisible();

    // Success by verified email: immediate row, Member role, no Pending.
    await page.getByLabel(authCopy.usernameOrEmail).fill('carol.writer@example.test');
    await page.getByRole('form').getByRole('button', { name: orgCopy.addMember }).click();
    await expect(page.getByText('carol-writer')).toBeVisible();
    await expect(page.getByText('Pending')).toHaveCount(0);
    await expect(page.getByText('carol-writer')).toHaveCount(1);
    await page.reload();
    await expect(page.getByText('carol-writer')).toBeVisible();
  });

  test('the new member sees the organization but gains no private repository access', async ({ browser }) => {
    const owner = await (await browser.newContext()).newPage();
    await signIn(owner, SEED_ACCOUNT.username, PASSWORD);
    await owner.goto('/orgs/acme-demo/people');
    await owner.getByRole('button', { name: orgCopy.addMember }).click();
    await owner.getByLabel(authCopy.usernameOrEmail).fill('carol-writer');
    await owner.getByRole('form').getByRole('button', { name: orgCopy.addMember }).click();
    await expect(owner.getByText('carol-writer')).toBeVisible();

    const member = await (await browser.newContext()).newPage();
    await signIn(member, 'carol-writer', PASSWORD);
    await member.getByRole('button', { name: authCopy.accountMenu }).click();
    await member.getByRole('link', { name: authCopy.yourOrganizations }).click();
    await expect(member.getByRole('link', { name: 'acme-demo' })).toBeVisible();

    // Private repository: signed-in without a grant → "Access denied" (PR #14
    // behavior); the API stays 404.
    const api = await member.request.get('/api/repos/acme-demo/org-private');
    expect([404, 403]).toContain(api.status());

    await member.goto('/acme-demo/org-private');
    await expect(
      member.getByRole('heading', { level: 1, name: errorCopy.accessDenied ?? errorCopy.notFound }),
    ).toBeVisible();
  });

  test('a visitor gets Not found on the private repository URL', async ({ page }) => {
    await page.goto('/acme-demo/org-private');
    await expect(page.getByRole('heading', { level: 1, name: errorCopy.notFound })).toBeVisible();
  });
});

test.describe('REQ-2-2-4 remove member', () => {
  test('Owner removes a member through the action menu and confirmation', async ({ page }) => {
    // Setup: make sure carol is a member (idempotent API would duplicate-error,
    // so reuse the UI add which tolerates the state left by earlier tests).
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/orgs/acme-demo/people');
    await expect(page.getByText('carol-writer')).toBeVisible();

    // The sole Owner has no member menu (UI 裁决点 3).
    await expect(page.getByRole('button', { name: orgCopy.memberMenu('alice-dev') })).toHaveCount(0);

    await page.getByRole('button', { name: orgCopy.memberMenu('carol-writer') }).click();
    await page.getByRole('menuitem', { name: orgCopy.removeFromOrganization }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog.getByRole('button', { name: orgCopy.remove })).toBeVisible();
    await dialog.getByRole('button', { name: orgCopy.remove }).click();

    await expect(page.getByText('carol-writer')).toHaveCount(0);
    await page.reload();
    await expect(page.getByText('carol-writer')).toHaveCount(0);
  });

  test('a non-Owner has no member menu and the removal API rejects them', async ({ page }) => {
    await signIn(page, 'bob-reviewer', PASSWORD);
    await page.goto('/orgs/acme-demo/people');
    await expect(page.getByRole('button', { name: orgCopy.memberMenu('alice-dev') })).toHaveCount(0);
    await expect(page.getByRole('button', { name: orgCopy.memberMenu('bob-reviewer') })).toHaveCount(0);

    const api = await page.request.delete('/api/orgs/acme-demo/members/alice-dev');
    expect(api.status()).toBe(403);
  });
});

test.describe('REQ-2-3 repository grants', () => {
  test('Owner grants a team Write access, re-saving stays unique, role replace works', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, PASSWORD);
    await page.goto('/acme-demo/org-private/settings');
    // The entry link added to the repository Settings page (admin-only).
    await expect(page.getByRole('link', { name: orgCopy.manageAccess })).toBeVisible();
    await page.getByRole('link', { name: orgCopy.manageAccess }).click();
    await expect(page).toHaveURL(/\/acme-demo\/org-private\/settings\/access$/);

    // Picker opens; the trigger is hidden while it is active.
    await page.getByRole('button', { name: orgCopy.addPeopleOrTeams }).click();
    await expect(page.getByRole('button', { name: orgCopy.addPeopleOrTeams })).toHaveCount(0);

    await page.getByRole('textbox', { name: orgCopy.search }).fill('frontend');
    await page.getByRole('option', { name: 'frontend-team' }).click();
    await page.getByLabel(orgCopy.role, { exact: true }).selectOption('write');
    await page.getByRole('button', { name: orgCopy.add, exact: true }).click();

    const row = page.getByRole('listitem').filter({ hasText: 'frontend-team' });
    await expect(row).toBeVisible();
    await expect(row.getByRole('combobox', { name: orgCopy.role })).toHaveValue('write');

    // Re-saving the same subject keeps exactly one record.
    await page.reload();
    await page.getByRole('button', { name: orgCopy.addPeopleOrTeams }).click();
    await page.getByRole('textbox', { name: orgCopy.search }).fill('frontend');
    await page.getByRole('option', { name: 'frontend-team' }).click();
    await page.getByLabel(orgCopy.role, { exact: true }).selectOption('write');
    await page.getByRole('button', { name: orgCopy.add, exact: true }).click();
    await page.reload();
    await expect(page.getByRole('listitem').filter({ hasText: 'frontend-team' })).toHaveCount(1);

    // Replace Write with Read on the existing row; exactly one row remains.
    const singleRow = page.getByRole('listitem').filter({ hasText: 'frontend-team' });
    await singleRow.getByRole('combobox', { name: orgCopy.role }).selectOption('read');
    await singleRow.getByRole('button', { name: orgCopy.save }).click();
    await page.reload();
    const rowAfter = page.getByRole('listitem').filter({ hasText: 'frontend-team' });
    await expect(rowAfter).toHaveCount(1);
    await expect(rowAfter.getByRole('combobox', { name: orgCopy.role })).toHaveValue('read');
  });

  test('a member with a team grant can access the private repository', async ({ browser }) => {
    // frontend-team holds a grant on org-handbook (seed); bob is its member.
    const member = await (await browser.newContext()).newPage();
    await signIn(member, 'bob-reviewer', PASSWORD);
    await member.goto('/acme-demo/org-handbook');
    await expect(member.getByRole('heading', { level: 1, name: 'acme-demo/org-handbook' })).toBeVisible();
  });

  test('a non-admin member sees neither the Manage access link nor the page, and the API rejects', async ({
    page,
  }) => {
    await signIn(page, 'bob-reviewer', PASSWORD);
    await page.goto('/acme-demo/org-private/settings');
    await expect(page.getByRole('link', { name: orgCopy.manageAccess })).toHaveCount(0);

    const api = await page.request.get('/api/repos/acme-demo/org-private/grants');
    expect(api.status()).toBe(403);

    await page.goto('/acme-demo/org-private/settings/access');
    await expect(page.getByText(errorCopy.forbidden)).toBeVisible();
  });
});

