export const SEED_PROTECTION_REPO = { owner: 'alice-dev', name: 'protection-lab' };

/**
 * M6b (REQ-6-5): the dedicated merge sandbox. `main` is protected with both
 * requirements, and three Open PRs (all authored by alice-dev) start in the
 * states the merge scenarios need: eligible (a preseeded non-author approve and
 * `test: success` for the current compare commit), blocked (no approval) and
 * review (no initial decision). It deliberately leaves acme-docs and
 * protection-lab untouched.
 */
export const SEED_MERGE_LAB_REPO = { owner: 'alice-dev', name: 'merge-lab' };
export const SEED_MERGE_LAB_TITLES = {
  eligible: 'Merge the onboarding notes',
  blocked: 'Merge the blocked notes',
  review: 'Merge the review notes',
};
export const SEED_MERGE_LAB_BRANCHES = {
  eligible: 'feature-eligible',
  blocked: 'feature-blocked',
  review: 'feature-review',
};

/**
 * `alice-dev/merge-lab`: the REQ-6-5 sandbox. Its `main` carries a protection
 * rule with both requirements, and its three Open PRs cover the eligible, blocked
 * and "needs a review" starting states. The approval and the `test: success` row
 * are only written while creating the eligible PR row, so a restart after a merge
 * keeps the merged PR, the advanced `main` and any user-made change untouched.
 */
function seedMergeLab(db, alice, bob, maintain) {
  const repo = ensureRepository(db, {
    ownerUserId: alice.id,
    name: SEED_MERGE_LAB_REPO.name,
    description: 'Sandbox for merging into a protected main branch',
    visibility: 'public',
  });

  const mainCommit = ensureCommit(db, {
    repoId: repo.id,
    authorId: alice.id,
    message: 'Add the merge policy',
    tree: {
      'README.md': '# merge-lab\n\nSandbox used by the merge scenarios.\n',
      'docs/policy.md': '# Policy\n\nMerging into main requires one approval and a successful test check.\n',
    },
    createdAt: daysAgo(3),
  });
  const main = ensureBranch(db, { repoId: repo.id, name: 'main', headCommitId: mainCommit.id });
  ensureDefaultBranch(db, repo, main);
  db.prepare(
    `INSERT OR IGNORE INTO branch_protections (repo_id, branch_name, require_approval, require_check_test)
     VALUES (?, 'main', 1, 1)`,
  ).run(repo.id);

  const mainTree = readTree(mainCommit.tree_json);
  const compareBranches = [
    [SEED_MERGE_LAB_BRANCHES.eligible, 'docs/eligible.md', '# Eligible\n\nReady to merge.\n'],
    [SEED_MERGE_LAB_BRANCHES.blocked, 'docs/blocked.md', '# Blocked\n\nStill waiting for an approval.\n'],
    [SEED_MERGE_LAB_BRANCHES.review, 'docs/review.md', '# Review\n\nPending review.\n'],
  ];
  for (const [name, path, content] of compareBranches) {
    const commit = ensureCommit(db, {
      repoId: repo.id,
      authorId: alice.id,
      message: `Add ${path}`,
      tree: withFile(mainTree, path, content),
      parentId: mainCommit.id,
      createdAt: hoursAgo(3),
    });
    ensureBranch(db, { repoId: repo.id, name, headCommitId: commit.id });
  }

  ensureGrant(db, repo.id, bob.id, 'write');
  ensureGrant(db, repo.id, maintain.id, 'maintain');

  const eligible = ensurePull(db, {
    repo,
    title: SEED_MERGE_LAB_TITLES.eligible,
    body: 'Merge the notes that already have an approval and a passing check.',
    authorId: alice.id,
    state: 'open',
    baseBranchName: 'main',
    compareBranchName: SEED_MERGE_LAB_BRANCHES.eligible,
    createdAt: hoursAgo(2),
  });

  // Only the eligible PR carries the REQ-6-5 GIVEN state, and only once: those
  // rows are the starting point of the merge scenario, not a runtime cache.
  const compareHead = branchByName(db, repo.id, SEED_MERGE_LAB_BRANCHES.eligible).head_commit_id;
  if (db.prepare('SELECT COUNT(*) AS n FROM reviews WHERE pr_id = ?').get(eligible.id).n === 0) {
    db.prepare(
      `INSERT INTO reviews (pr_id, reviewer_id, decision, summary, compare_commit_id, created_at)
       VALUES (?, ?, 'approve', ?, ?, ?)`,
    ).run(eligible.id, bob.id, 'Ready to merge.', compareHead, hoursAgo(2));
  }
  db.prepare(
    `INSERT OR IGNORE INTO check_runs (pr_id, compare_commit_id, name, status, setter_id, updated_at)
     VALUES (?, ?, 'test', 'success', ?, ?)`,
  ).run(eligible.id, compareHead, alice.id, hoursAgo(2));

  ensurePull(db, {
    repo,
    title: SEED_MERGE_LAB_TITLES.blocked,
    body: 'The target branch still requires an approval.',
    authorId: alice.id,
    state: 'open',
    baseBranchName: 'main',
    compareBranchName: SEED_MERGE_LAB_BRANCHES.blocked,
    createdAt: hoursAgo(2),
  });
  ensurePull(db, {
    repo,
    title: SEED_MERGE_LAB_TITLES.review,
    body: 'Receives the reviews written in the acceptance scenarios.',
    authorId: alice.id,
    state: 'open',
    baseBranchName: 'main',
    compareBranchName: SEED_MERGE_LAB_BRANCHES.review,
    createdAt: hoursAgo(2),
  });
}

/** @param {import('better-sqlite3').Database} db */
export function seedPulls(db) {
  const alice = userByUsername(db, 'alice-dev');
  const bob = userByUsername(db, 'bob-reviewer');
