/**
 * Issue seed data (docs/seed-data.md — M5 share: labels, milestones, issues,
 * comments, assignees and cross-repository isolation samples).
 *
 * Every object is keyed by its business identity and written insert-if-absent, and
 * the associations of a seeded issue are only written together with the issue row
 * itself. Re-running the seed (every application start) therefore never overwrites
 * data a user produced: an edited title stays edited, a removed label stays
 * removed, a closed issue stays closed.
 *
 * Cross-repository isolation (REQ-5-3-2/5-3-3) needs a *second* repository that
 * carries both a label/milestone with the same name as acme-docs and one with a
 * different name, so a selector leaking foreign objects is observable in both
 * shapes.
 */
import { registerSeed } from './index.js';
import { insertActivity } from '../modules/issues/service.js';

/** Issue titles the requirement text asserts (REQ-5-1-1 / REQ-5-2-2). */
export const SEED_ISSUE_TITLES = {
  open: 'Improve onboarding',
  closed: 'Legacy welcome text',
  editable: 'Original issue title',
};
/** Description the requirement text asserts for the open issue (REQ-5-1-2). */
export const SEED_OPEN_ISSUE_BODY = 'Describe the onboarding improvement.';

const SEED_LABELS = { acmeDocs: ['bug', 'documentation'], secretResearch: ['bug', 'private-ops'] };
const SEED_MILESTONES = { acmeDocs: ['Q3 launch', 'v1.0'], secretResearch: ['Q3 launch', 'Private roadmap'] };

function userByUsername(db, username) {
  const row = db.prepare('SELECT * FROM users WHERE username = ?').get(username);
  if (!row) throw new Error(`seed(issues): account "${username}" must exist before the issue seed runs`);
  return row;
}

function repoByOwnerAndName(db, owner, name) {
  const row = db
    .prepare(
      `SELECT r.* FROM repos r
         LEFT JOIN users u ON u.id = r.owner_user_id
         LEFT JOIN organizations o ON o.id = r.owner_org_id
        WHERE r.name = ? AND COALESCE(u.username, o.name) = ?`,
    )
    .get(name, owner);
  if (!row) throw new Error(`seed(issues): repository "${owner}/${name}" must exist before the issue seed runs`);
  return row;
}

/** Insert-if-absent by business key; returns `{row, created}`. */
function ensure(db, selectSql, selectArgs, insert) {
  const existing = db.prepare(selectSql).get(...selectArgs);
  if (existing) return { row: existing, created: false };
  return { row: insert(), created: true };
}

function ensureLabel(db, repoId, name) {
  const { row } = ensure(
    db,
    'SELECT * FROM labels WHERE repo_id = ? AND name = ?',
    [repoId, name],
    () => db.prepare('INSERT INTO labels (repo_id, name) VALUES (?, ?) RETURNING *').get(repoId, name),
  );
  return row;
}

function ensureMilestone(db, repoId, title) {
  const { row } = ensure(
    db,
    'SELECT * FROM milestones WHERE repo_id = ? AND title = ?',
    [repoId, title],
    () => db.prepare('INSERT INTO milestones (repo_id, title) VALUES (?, ?) RETURNING *').get(repoId, title),
  );
  return row;
}

/** Issues are keyed by (repository, number); the seeded numbers are 1..3. */
function ensureIssue(db, { repoId, number, title, body, authorId, state, createdAt, closedAt = null }) {
  return ensure(
    db,
    'SELECT * FROM issues WHERE repo_id = ? AND number = ?',
    [repoId, number],
    () => {
      const issue = db
        .prepare(
          `INSERT INTO issues (repo_id, number, title, body, author_id, state, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?) RETURNING *`,
        )
        .get(repoId, number, title, body, authorId, state, createdAt, closedAt ?? createdAt);
      insertActivity(db, {
        kind: 'issue_opened',
        actorId: authorId,
        subjectId: issue.id,
        payload: { number, title },
        createdAt,
      });
      if (state === 'closed') {
        insertActivity(db, {
          kind: 'issue_closed',
          actorId: authorId,
          subjectId: issue.id,
          payload: {},
          createdAt: closedAt ?? createdAt,
        });
      }
      return issue;
    },
  );
}

function addSeedComment(db, { issue, authorId, body, createdAt }) {
  const existing = db.prepare('SELECT 1 AS ok FROM comments WHERE issue_id = ? AND author_id = ?').get(issue.id, authorId);
  if (existing) return;
  const comment = db
    .prepare('INSERT INTO comments (issue_id, author_id, body, created_at) VALUES (?, ?, ?, ?) RETURNING *')
    .get(issue.id, authorId, body, createdAt);
  insertActivity(db, {
    kind: 'commented',
    actorId: authorId,
    subjectId: issue.id,
    payload: { commentId: comment.id },
    createdAt,
  });
  db.prepare('UPDATE issues SET updated_at = ? WHERE id = ?').run(createdAt, issue.id);
}

function ensureIssueLabel(db, issueId, labelId) {
  db.prepare('INSERT OR IGNORE INTO issue_labels (issue_id, label_id) VALUES (?, ?)').run(issueId, labelId);
}

function ensureIssueMilestone(db, issueId, milestoneId) {
  db.prepare('INSERT OR IGNORE INTO issue_milestones (issue_id, milestone_id) VALUES (?, ?)').run(issueId, milestoneId);
}

function ensureAssignee(db, issueId, userId) {
  db.prepare('INSERT OR IGNORE INTO assignees (issue_id, user_id) VALUES (?, ?)').run(issueId, userId);
}

function ensureGrant(db, repoId, userId, role) {
  db.prepare('INSERT OR IGNORE INTO repo_grants (repo_id, subject_user_id, role) VALUES (?, ?, ?)').run(
    repoId,
    userId,
    role,
  );
}

/** @param {import('better-sqlite3').Database} db */
export function seedIssues(db) {
  const alice = userByUsername(db, 'alice-dev');
  const bob = userByUsername(db, 'bob-reviewer');
  const dave = userByUsername(db, 'dave-reader');
  const acmeDocs = repoByOwnerAndName(db, 'alice-dev', 'acme-docs');
  const secret = repoByOwnerAndName(db, 'alice-dev', 'secret-research');

  for (const name of SEED_LABELS.acmeDocs) ensureLabel(db, acmeDocs.id, name);
  for (const name of SEED_LABELS.secretResearch) ensureLabel(db, secret.id, name);
  for (const title of SEED_MILESTONES.acmeDocs) ensureMilestone(db, acmeDocs.id, title);
  for (const title of SEED_MILESTONES.secretResearch) ensureMilestone(db, secret.id, title);

  const bug = ensureLabel(db, acmeDocs.id, 'bug');
  const documentation = ensureLabel(db, acmeDocs.id, 'documentation');
  const q3 = ensureMilestone(db, acmeDocs.id, 'Q3 launch');

  // Open issue: title, description, two labels, a milestone, one assignee and one
  // comment (REQ-5-1-2 / REQ-5-2-3 / REQ-5-3-*).
  const open = ensureIssue(db, {
    repoId: acmeDocs.id,
    number: 1,
    title: SEED_ISSUE_TITLES.open,
    body: SEED_OPEN_ISSUE_BODY,
    authorId: alice.id,
    state: 'open',
    createdAt: '2024-05-01 09:00:00',
  });
  if (open.created) {
    ensureIssueLabel(db, open.row.id, bug.id);
    ensureIssueLabel(db, open.row.id, documentation.id);
    ensureIssueMilestone(db, open.row.id, q3.id);
    ensureAssignee(db, open.row.id, bob.id);
    addSeedComment(db, {
      issue: open.row,
      authorId: bob.id,
      body: 'Thanks for writing this up — onboarding is the biggest gap we have.',
      createdAt: '2024-05-01 09:05:00',
    });
  }

  // Closed issue: the Closed-status filter sample (REQ-5-1-1).
  const closed = ensureIssue(db, {
    repoId: acmeDocs.id,
    number: 2,
    title: SEED_ISSUE_TITLES.closed,
    body: 'The welcome text still mentions the old product name.',
    authorId: alice.id,
    state: 'closed',
    createdAt: '2024-05-02 09:00:00',
    closedAt: '2024-05-03 09:00:00',
  });
  if (closed.created) ensureIssueLabel(db, closed.row.id, bug.id);

  // Clean issue used by the "blank title keeps the original value" branch
  // (REQ-5-2-2) and by the metadata scenarios.
  ensureIssue(db, {
    repoId: acmeDocs.id,
    number: 3,
    title: SEED_ISSUE_TITLES.editable,
    body: 'This description is the original one and must survive an invalid edit.',
    authorId: alice.id,
    state: 'open',
    createdAt: '2024-05-04 09:00:00',
  });

  // Read-only collaborator: not assignable (REQ-5-3-1 / Issue #8 comment #89 D9).
  ensureGrant(db, acmeDocs.id, dave.id, 'read');
}

registerSeed('issues', seedIssues);

