/**
 * Organizations & governance module (REQ-2, docs/architecture.md §3/§4/§5).
 *
 * Read endpoints of the public organization pages are open to visitors; every
 * write endpoint requires the organization Owner role (REQ-2-2: "Only an
 * organization Owner may maintain members or hierarchy"). Permission checks all
 * go through `permissions/index.js` — the single implementation of the model
 * (org Owner → admin, direct/team grants take the highest, hierarchy never
 * propagates).
 */
import { Router } from 'express';
import { transact } from '../../db/index.js';
import { requireAuth } from '../../auth/middleware.js';
import { ApiError, fieldError, forbidden, notFound, validationError } from '../../http/errors.js';
import { messages } from '../../contracts/messages.js';
import {
  collectErrors,
  validateDisplayName,
  validateOrgName,
  validateTeamName,
} from '../../http/validate.js';
import { effectiveRepoRole, orgRole } from '../../permissions/index.js';

/** `Member`/`Owner` (UI labels) and `member`/`owner` are both accepted. */
function normalizeOrgRole(raw) {
  const value = typeof raw === 'string' ? raw.trim().toLowerCase() : '';
  if (value === 'member' || value === 'owner') return value;
  return null;
}

/** Latest commit time of a repository, falling back to its creation time. */
function repoUpdatedAt(db, repo) {
  const row = db.prepare('SELECT MAX(created_at) AS at FROM commits WHERE repo_id = ?').get(repo.id);
  return row?.at ?? repo.created_at;
}

/**
 * Resolve the organization by identifier or throw 404. Only the identifier is
 * matched (never the display name), so nothing about display names leaks.
 */
function loadOrg(db, name) {
  const org = db.prepare('SELECT * FROM organizations WHERE name = ?').get(String(name));
  if (!org) throw notFound();
  return org;
}

/** Owner gate for every write endpoint (REQ-2-2). */
function requireOrgOwner(db, req, org) {
  if (orgRole(db, req.user, org.id) !== 'owner') throw forbidden();
}

/** Find an account by username or verified email (REQ-2-2-3). */
function findAccount(db, identifier) {
  const value = String(identifier ?? '').trim();
  if (!value) return null;
  return db
    .prepare('SELECT * FROM users WHERE username = ? OR (email = ? AND email_verified = 1)')
    .get(value, value.toLowerCase());
}

/** Public shape of an organization row. */
function publicOrg(org) {
  return { name: org.name, displayName: org.display_name, createdAt: org.created_at };
}

/**
 * Repositories of the organization visible to `user`: public ones always,
 * private ones only with a non-null effective role (an ordinary organization
 * Member has no default private access — REQ-2-3).
 */
function visibleOrgRepositories(db, user, org) {
  const repos = db
    .prepare('SELECT * FROM repos WHERE owner_org_id = ? ORDER BY name')
    .all(org.id);
  return repos
    .filter((repo) => repo.visibility === 'public' || effectiveRepoRole(db, user, repo) != null)
    .map((repo) => ({
      name: repo.name,
      description: repo.description,
      visibility: repo.visibility,
      updatedAt: repoUpdatedAt(db, repo),
    }));
}

/** True when setting `team`'s parent to `newParentId` would create a cycle. */
function wouldCreateCycle(db, team, newParentId) {
  let cursor = newParentId;
  const seen = new Set();
  while (cursor != null && !seen.has(cursor)) {
    if (cursor === team.id) return true;
    seen.add(cursor);
    const row = db.prepare('SELECT parent_team_id AS parent FROM teams WHERE id = ?').get(cursor);
    cursor = row?.parent ?? null;
  }
  return false;
}

export function createOrgsRouter({ db }) {
  const router = Router();

  /** "Your organizations" (REQ-2-1-2): the current user's memberships. */
  router.get('/', requireAuth, (req, res) => {
    const organizations = db
      .prepare(
        `SELECT o.name, o.display_name, m.role
           FROM org_members m JOIN organizations o ON o.id = m.org_id
          WHERE m.user_id = ? ORDER BY o.name`,
      )
      .all(req.user.id)
      .map((row) => ({ name: row.name, displayName: row.display_name, role: row.role }));
    res.json({ organizations });
  });

  /** Create an organization (REQ-2-1-2). All field problems are reported at once. */
  router.post('/', requireAuth, (req, res) => {
    const body = req.body ?? {};
    const name = validateOrgName(body.name);
    const displayName = validateDisplayName(body.displayName ?? body.display_name);

    const errors = collectErrors([name, displayName]);
    if (name.ok) {
      const existing = db.prepare('SELECT id FROM organizations WHERE name = ?').get(name.value);
      // The duplicate identifier is reported even when the display name is also
      // missing (REQ-2-1-2: both messages on one submission).
      if (existing) {
        errors.unshift(fieldError('org_name_exists', messages.ORG_NAME_EXISTS, 'name'));
      }
    }
    if (errors.length) throw validationError(errors);

    const org = transact(db, () => {
      const created = db
        .prepare('INSERT INTO organizations (name, display_name) VALUES (?, ?) RETURNING *')
        .get(name.value, displayName.value);
      db.prepare("INSERT INTO org_members (org_id, user_id, role) VALUES (?, ?, 'owner')").run(
        created.id,
        req.user.id,
      );
      return created;
    });

    res.status(201).json({ organization: publicOrg(org) });
  });

  /** Organization overview (public — visitors browse public organization pages). */
  router.get('/:org', (req, res) => {
    const org = loadOrg(db, req.params.org);
    res.json({
      organization: publicOrg(org),
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** Repositories tab (REQ-2-1-1): only repositories visible to the current user. */
  router.get('/:org/repositories', (req, res) => {
    const org = loadOrg(db, req.params.org);
    res.json({
      organization: publicOrg(org),
      repositories: visibleOrgRepositories(db, req.user, org),
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** People tab (REQ-2-2-3/2-2-4): the member list with Member/Owner roles. */
  router.get('/:org/people', (req, res) => {
    const org = loadOrg(db, req.params.org);
    const members = db
      .prepare(
        `SELECT u.username, m.role
           FROM org_members m JOIN users u ON u.id = m.user_id
          WHERE m.org_id = ? ORDER BY u.username`,
      )
      .all(org.id);
    res.json({
      organization: publicOrg(org),
      members,
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** Directly add a member (REQ-2-2-3) — Owner only, no invitation step. */
  router.post('/:org/members', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);

    const body = req.body ?? {};
    const role = normalizeOrgRole(body.role ?? 'member');
    const errors = [];
    if (!role) errors.push(fieldError('role_invalid', messages.ROLE_INVALID, 'role'));
    const identifier = String(body.usernameOrEmail ?? body.username ?? '').trim();
    const account = identifier ? findAccount(db, identifier) : null;
    if (!account) errors.push(fieldError('account_not_found', messages.ACCOUNT_NOT_FOUND, 'usernameOrEmail'));
    if (account) {
      const existing = db
        .prepare('SELECT 1 FROM org_members WHERE org_id = ? AND user_id = ?')
        .get(org.id, account.id);
      if (existing) {
        errors.push(fieldError('account_already_member', messages.ACCOUNT_ALREADY_MEMBER, 'usernameOrEmail'));
      }
    }
    if (errors.length) throw validationError(errors);

    transact(db, () => {
      db.prepare('INSERT INTO org_members (org_id, user_id, role) VALUES (?, ?, ?)').run(
        org.id,
        account.id,
        role,
      );
    });
    res.status(201).json({ member: { username: account.username, role } });
  });

  /**
   * Remove a member (REQ-2-2-4). Atomically deletes the organization membership,
   * all team memberships in this organization and all direct grants on this
   * organization's repositories. The account, personal repositories, the teams
   * themselves and team grants are never touched.
   */
  router.delete('/:org/members/:username', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);

    const target = db
      .prepare(
        `SELECT u.id, u.username, m.role FROM org_members m
           JOIN users u ON u.id = m.user_id
          WHERE m.org_id = ? AND u.username = ?`,
      )
      .get(org.id, req.params.username);
    if (!target) throw notFound();

    const ownerCount = db
      .prepare("SELECT COUNT(*) AS n FROM org_members WHERE org_id = ? AND role = 'owner'")
      .get(org.id).n;
    if (target.role === 'owner' && ownerCount <= 1) {
      throw new ApiError(422, 'cannot_remove_last_owner', messages.CANNOT_REMOVE_LAST_OWNER);
    }

    transact(db, () => {
      db.prepare('DELETE FROM org_members WHERE org_id = ? AND user_id = ?').run(org.id, target.id);
      db.prepare(
        `DELETE FROM team_members WHERE user_id = ? AND team_id IN (SELECT id FROM teams WHERE org_id = ?)`,
      ).run(target.id, org.id);
      db.prepare(
        `DELETE FROM repo_grants WHERE subject_user_id = ? AND repo_id IN (SELECT id FROM repos WHERE owner_org_id = ?)`,
      ).run(target.id, org.id);
    });
    res.json({ ok: true });
  });

  /** Teams tab (REQ-2-2-1): the organization's teams with their parents. */
  router.get('/:org/teams', (req, res) => {
    const org = loadOrg(db, req.params.org);
    const teams = db
      .prepare(
        `SELECT t.name, t.description, p.name AS parent
           FROM teams t LEFT JOIN teams p ON p.id = t.parent_team_id
          WHERE t.org_id = ? ORDER BY t.name`,
      )
      .all(org.id);
    res.json({
      organization: publicOrg(org),
      teams,
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** Create a team (REQ-2-2-1) — Owner only. */
  router.post('/:org/teams', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);

    const body = req.body ?? {};
    const name = validateTeamName(body.name);
    const description = typeof body.description === 'string' ? body.description.trim() : '';
    const errors = collectErrors([name]);
    if (name.ok) {
      const existing = db
        .prepare('SELECT id FROM teams WHERE org_id = ? AND name = ?')
        .get(org.id, name.value);
      if (existing) errors.push(fieldError('team_name_exists', messages.TEAM_NAME_EXISTS, 'name'));
    }

    let parentTeamId = null;
    const parentName = typeof body.parentTeam === 'string' ? body.parentTeam.trim() : '';
    if (parentName) {
      const parent = db
        .prepare('SELECT id FROM teams WHERE org_id = ? AND name = ?')
        .get(org.id, parentName);
      if (!parent) {
        errors.push(fieldError('parent_team_invalid', messages.PARENT_TEAM_INVALID, 'parentTeam'));
      } else {
        parentTeamId = parent.id;
      }
    }
    if (errors.length) throw validationError(errors);

    const team = transact(db, () =>
      db
        .prepare('INSERT INTO teams (org_id, name, description, parent_team_id) VALUES (?, ?, ?, ?) RETURNING *')
        .get(org.id, name.value, description, parentTeamId),
    );
    res.status(201).json({ team: { name: team.name, description: team.description, parent: parentName || null } });
  });

  /** Team detail page (REQ-2-2-2) — heading is `org/team`. */
  router.get('/:org/teams/:team', (req, res) => {
    const org = loadOrg(db, req.params.org);
    const team = db
      .prepare(
        `SELECT t.*, p.name AS parent_name FROM teams t
           LEFT JOIN teams p ON p.id = t.parent_team_id
          WHERE t.org_id = ? AND t.name = ?`,
      )
      .get(org.id, req.params.team);
    if (!team) throw notFound();
    res.json({
      organization: publicOrg(org),
      team: {
        name: team.name,
        description: team.description,
        parent: team.parent_name ?? null,
      },
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** Change the parent team (REQ-2-2-2) — cycles are rejected, original kept. */
  router.patch('/:org/teams/:team', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);
    const team = db
      .prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?')
      .get(org.id, req.params.team);
    if (!team) throw notFound();

    const body = req.body ?? {};
    const rawParent = body.parentTeam ?? body.parent_team;
    let parentTeamId = null;
    let parentName = null;
    if (rawParent != null && String(rawParent).trim() !== '') {
      const parent = db
        .prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?')
        .get(org.id, String(rawParent).trim());
      if (!parent) {
        throw validationError([fieldError('parent_team_invalid', messages.PARENT_TEAM_INVALID, 'parentTeam')]);
      }
      if (wouldCreateCycle(db, team, parent.id)) {
        // Rejected without writing: the original parent is kept (REQ-2-2-2).
        throw new ApiError(422, 'cyclic_team_hierarchy', messages.CYCLIC_TEAM_HIERARCHY);
      }
      parentTeamId = parent.id;
      parentName = parent.name;
    }

    transact(db, () => {
      db.prepare('UPDATE teams SET parent_team_id = ? WHERE id = ?').run(parentTeamId, team.id);
    });
    res.json({ team: { name: team.name, description: team.description, parent: parentName } });
  });

  /** Team Members tab (REQ-2-2-2): the team's direct members. */
  router.get('/:org/teams/:team/members', (req, res) => {
    const org = loadOrg(db, req.params.org);
    const team = db.prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?').get(org.id, req.params.team);
    if (!team) throw notFound();
    const members = db
      .prepare(
        `SELECT u.username FROM team_members tm JOIN users u ON u.id = tm.user_id
          WHERE tm.team_id = ? ORDER BY u.username`,
      )
      .all(team.id);
    res.json({
      team: { name: team.name },
      members,
      viewerPermission: { organization: orgRole(db, req.user, org.id), canView: true },
    });
  });

  /** Add a team member (REQ-2-2-2) — Owner only; must be an organization member. */
  router.post('/:org/teams/:team/members', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);
    const team = db.prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?').get(org.id, req.params.team);
    if (!team) throw notFound();

    const account = findAccount(db, req.body?.username);
    if (!account) {
      throw validationError([fieldError('account_not_found', messages.ACCOUNT_NOT_FOUND, 'username')]);
    }
    const isMember = db.prepare('SELECT 1 FROM org_members WHERE org_id = ? AND user_id = ?').get(org.id, account.id);
    if (!isMember) {
      throw validationError([
        fieldError('account_not_org_member', messages.ACCOUNT_NOT_ORG_MEMBER, 'username'),
      ]);
    }

    // Team membership is idempotent: adding twice leaves one relationship.
    transact(db, () => {
      db.prepare('INSERT OR IGNORE INTO team_members (team_id, user_id) VALUES (?, ?)').run(team.id, account.id);
    });
    res.status(201).json({ member: { username: account.username } });
  });

  /** Remove a team member (REQ-2-2-2) — Owner only, immediate, no confirmation. */
  router.delete('/:org/teams/:team/members/:username', requireAuth, (req, res) => {
    const org = loadOrg(db, req.params.org);
    requireOrgOwner(db, req, org);
    const team = db.prepare('SELECT * FROM teams WHERE org_id = ? AND name = ?').get(org.id, req.params.team);
    if (!team) throw notFound();
    const account = db.prepare('SELECT id FROM users WHERE username = ?').get(req.params.username);
    if (!account) throw notFound();
    transact(db, () => {
      db.prepare('DELETE FROM team_members WHERE team_id = ? AND user_id = ?').run(team.id, account.id);
    });
    res.json({ ok: true });
  });

  return router;
}

export default createOrgsRouter;

