/**
 * M6b pull request review tests (REQ-6-3-3 inline comments, REQ-6-3-4 submitted
 * reviews, REQ-6-4 reviewers, REQ-6-5 merge gating, REQ-6-6 close/reopen).
 *
 * They run against the real HTTP application and the real seed data
 * (docs/seed-data.md) like `pulls.test.js`. The merge sandbox is
 * `alice-dev/merge-lab` (REQ-6-5 initial states); acme-docs keeps providing the
 * non-author Write reviewer (bob-reviewer), the author (alice-dev) and the
 * read-only counter-example (dave-reader). Every test starts from its own
 * in-memory database, so mutations never leak between cases.
 */
import { describe, expect, it } from 'vitest';
import { messages } from '../src/contracts/messages.js';
import { readTree } from '../src/modules/content/history.js';
import { diffTrees } from '../src/modules/content/diff.js';
import { SEED_ACCOUNT_PASSWORD } from '../src/seed/accounts.js';
import { SEED_PUBLIC_REPO } from '../src/seed/repos.js';
import { SEED_MERGE_LAB_BRANCHES, SEED_MERGE_LAB_REPO, SEED_MERGE_LAB_TITLES } from '../src/seed/pulls.js';
import { runSeeds } from '../src/seed/index.js';
import { createClient, startTestServer } from './helpers.js';

const ACME = `/api/repos/${SEED_PUBLIC_REPO.owner}/${SEED_PUBLIC_REPO.name}`;
const ACME_PULL = (number) => `${ACME}/pulls/${number}`;
const LAB = `/api/repos/${SEED_MERGE_LAB_REPO.owner}/${SEED_MERGE_LAB_REPO.name}`;
const LAB_PULL = (number) => `${LAB}/pulls/${number}`;

async function withServer(run) {
  const server = await startTestServer();
  try {
    await run(server);
  } finally {
    await server.close();
  }
}

async function signInAs(client, username) {
  const response = await client.post('/api/auth/sign-in', { identifier: username, password: SEED_ACCOUNT_PASSWORD });
  expect(response.status).toBe(200);
}

function pullByTitle(db, repoName, title) {
  return db
    .prepare(
      `SELECT p.* FROM pull_requests p JOIN repos r ON r.id = p.repo_id WHERE r.name = ? AND p.title = ?`,
    )
    .get(repoName, title);
}

function repoByName(db, name) {
  return db.prepare('SELECT * FROM repos WHERE name = ?').get(name);
}

function branchByName(db, repoId, name) {
  return db.prepare('SELECT * FROM branches WHERE repo_id = ? AND name = ?').get(repoId, name);
}

function commitById(db, id) {
  return db.prepare('SELECT * FROM commits WHERE id = ?').get(id);
}

/** Append a commit to a branch with the given tree and move the head. */
function pushCommit(db, { repo, branch, authorId, message, tree, parentId }) {
  const commit = db
    .prepare(
      `INSERT INTO commits (repo_id, parent_id, author_id, message, tree_json)
       VALUES (?, ?, ?, ?, ?) RETURNING *`,
    )
    .get(repo.id, parentId, authorId, message, JSON.stringify(tree));
  db.prepare('UPDATE branches SET head_commit_id = ? WHERE id = ?').run(commit.id, branch.id);
  return commit;
}

function countRows(db, table) {
  return db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get().n;
}

/** First added line of one file of the PR's current diff, or a deleted one. */
function anchorOf(comparison, path, type = 'added') {
  const file = comparison.body.files.find((entry) => entry.path === path);
  const line = file.lines.find((entry) => entry.type === type);
  return { path, side: type === 'added' ? 'new' : 'old', line: type === 'added' ? line.newNumber : line.oldNumber };
}

describe('inline review comments (REQ-6-3-3)', () => {
  it('lets a non-author Write reviewer publish immediately and keeps it after reload', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const comparison = await bob.get(`${ACME}/pulls/compare?base=main&compare=pr-onboarding`);
      const anchor = anchorOf(comparison, 'src/search.ts', 'deleted');

      const created = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        ...anchor,
        body: 'Why is this line removed?',
        pending: false,
      });
      expect(created.status).toBe(201);
      expect(created.body.comment).toMatchObject({
        path: 'src/search.ts',
        side: 'old',
        body: 'Why is this line removed?',
        author: 'bob-reviewer',
        published: true,
        outdated: false,
      });

      const reloaded = await bob.get(ACME_PULL(1));
      expect(reloaded.body.reviewComments).toHaveLength(1);
      expect(reloaded.body.reviewComments[0]).toMatchObject({
        id: created.body.comment.id,
        line: anchor.line,
        side: 'old',
      });

      // The visitor reads the published comment as well (it is public).
      const visitor = createClient(server.baseUrl);
      const visitorView = await visitor.get(ACME_PULL(1));
      expect(visitorView.body.reviewComments.map((comment) => comment.id)).toEqual([created.body.comment.id]);
    });
  });

  it('keeps a pending draft private until the review is submitted, then publishes it', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const comparison = await bob.get(`${ACME}/pulls/compare?base=main&compare=pr-onboarding`);
      const anchor = anchorOf(comparison, 'docs/onboarding.md');

      const draft = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        ...anchor,
        body: 'Draft note',
        pending: true,
      });
      expect(draft.status).toBe(201);
      expect(draft.body.comment.published).toBe(false);

      // Only its author sees the draft.
      const own = await bob.get(ACME_PULL(1));
      expect(own.body.reviewComments.map((comment) => comment.published)).toEqual([false]);
      const visitor = createClient(server.baseUrl);
      expect((await visitor.get(ACME_PULL(1))).body.reviewComments).toEqual([]);
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      expect((await alice.get(ACME_PULL(1))).body.reviewComments).toEqual([]);

      // Submitting the review publishes the draft in the same transaction.
      const review = await bob.post(`${ACME_PULL(1)}/reviews`, { decision: 'comment', summary: 'See inline.' });
      expect(review.status).toBe(201);
      expect(review.body.publishedComments).toBe(1);
      expect(review.body.reviewComments).toHaveLength(1);
      expect(review.body.reviewComments[0]).toMatchObject({ body: 'Draft note', published: true });
      expect((await visitor.get(ACME_PULL(1))).body.reviewComments).toHaveLength(1);
    });
  });

  it('marks comments Outdated when the compare commit changes, without relocating them', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const comparison = await bob.get(`${ACME}/pulls/compare?base=main&compare=pr-onboarding`);
      const anchor = anchorOf(comparison, 'docs/onboarding.md');
      const created = await bob.post(`${ACME_PULL(1)}/review-comments`, { ...anchor, body: 'Anchored', pending: false });
      const originalCommit = created.body.comment.compareCommitId;

      const repo = repoByName(server.db, SEED_PUBLIC_REPO.name);
      const branch = branchByName(server.db, repo.id, 'pr-onboarding');
      const head = commitById(server.db, branch.head_commit_id);
      pushCommit(server.db, {
        repo,
        branch,
        authorId: head.author_id,
        message: 'Follow-up onboarding commit',
        tree: readTree(head.tree_json),
        parentId: head.id,
      });

      const after = await bob.get(ACME_PULL(1));
      expect(after.body.reviewComments[0]).toMatchObject({
        path: 'docs/onboarding.md',
        line: anchor.line,
        compareCommitId: originalCommit,
        outdated: true,
      });
    });
  });

  it('rejects empty bodies and anchors that are not changed lines without leaving rows', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const before = countRows(server.db, 'review_comments');

      const blank = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        path: 'docs/onboarding.md',
        line: 1,
        side: 'new',
        body: '   ',
      });
      expect(blank.status).toBe(422);
      expect(blank.body.error.message).toBe(messages.COMMENT_REQUIRED);

      const badSide = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        path: 'docs/onboarding.md',
        line: 1,
        side: 'middle',
        body: 'nope',
      });
      expect(badSide.status).toBe(422);
      expect(badSide.body.error.message).toBe(messages.REVIEW_SIDE_INVALID);

      const badLine = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        path: 'docs/onboarding.md',
        line: 9999,
        side: 'new',
        body: 'nope',
      });
      expect(badLine.status).toBe(422);
      expect(badLine.body.error.message).toBe(messages.REVIEW_ANCHOR_INVALID);

      const wrongSide = await bob.post(`${ACME_PULL(1)}/review-comments`, {
        path: 'docs/onboarding.md',
        line: 1,
        side: 'old',
        body: 'nope',
      });
      expect(wrongSide.status).toBe(422);
      expect(countRows(server.db, 'review_comments')).toBe(before);
    });
  });
});

describe('submitted reviews (REQ-6-3-4)', () => {
  it('enforces the review permission set and Open-only state', async () => {
    await withServer(async (server) => {
      const comment = { path: 'docs/onboarding.md', line: 1, side: 'new', body: 'x' };

      const visitor = createClient(server.baseUrl);
      expect((await visitor.post(`${ACME_PULL(1)}/review-comments`, comment)).status).toBe(401);
      expect((await visitor.post(`${ACME_PULL(1)}/reviews`, { decision: 'approve' })).status).toBe(401);

      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      expect((await alice.post(`${ACME_PULL(1)}/review-comments`, comment)).status).toBe(403);
      expect((await alice.post(`${ACME_PULL(1)}/reviews`, { decision: 'approve' })).status).toBe(403);

      const dave = createClient(server.baseUrl);
      await signInAs(dave, 'dave-reader');
      expect((await dave.post(`${ACME_PULL(1)}/review-comments`, comment)).status).toBe(403);

      const triage = createClient(server.baseUrl);
      await signInAs(triage, 'pw-triage');
      expect((await triage.post(`${ACME_PULL(1)}/reviews`, { decision: 'approve' })).status).toBe(403);

      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      expect((await bob.post(`${ACME_PULL(1)}/review-comments`, comment)).status).toBe(201);

      // Draft and Closed PRs cannot receive reviews (REQ-6-3-4).
      const draft = pullByTitle(server.db, SEED_PUBLIC_REPO.name, 'Draft onboarding update');
      const closed = pullByTitle(server.db, SEED_PUBLIC_REPO.name, 'Close the legacy welcome text');
      expect((await bob.post(`${ACME}/pulls/${draft.number}/reviews`, { decision: 'approve' })).status).toBe(403);
      expect((await bob.post(`${ACME}/pulls/${closed.number}/reviews`, { decision: 'approve' })).status).toBe(403);
    });
  });

  it('keeps the newest decision per reviewer and preserves the older records', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.review).number;

      expect((await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'approve', summary: 'LGTM' })).status).toBe(201);
      const requested = await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'request_changes', summary: 'Please fix' });
      expect(requested.status).toBe(201);
      expect(requested.body.reviews.at(-1)).toMatchObject({ decision: 'request_changes', summary: 'Please fix' });

      let detail = await bob.get(LAB_PULL(number));
      expect(detail.body.reviews.map((review) => review.decision)).toEqual(['approve', 'request_changes']);
      expect(detail.body.merge).toMatchObject({ eligible: false, changesRequested: true });

      // A new Comment decision clears the block but is not an approval.
      const comment = await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'comment', summary: '' });
      expect(comment.status).toBe(201);
      detail = await bob.get(LAB_PULL(number));
      expect(detail.body.reviews).toHaveLength(3);
      expect(detail.body.merge).toMatchObject({ changesRequested: false, approval: { satisfied: false } });
      expect(detail.body.merge.reasons.map((reason) => reason.code)).toEqual(['approval_required']);

      // Approving again makes the protected PR eligible.
      await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'approve', summary: '' });
      detail = await bob.get(LAB_PULL(number));
      expect(detail.body.merge).toMatchObject({ eligible: false, check: { satisfied: false } });
    });
  });

  it('invalidates decisions when the compare commit advances (stale)', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.review).number;
      await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'approve', summary: '' });

      const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
      const branch = branchByName(server.db, repo.id, SEED_MERGE_LAB_BRANCHES.review);
      const head = commitById(server.db, branch.head_commit_id);
      pushCommit(server.db, {
        repo,
        branch,
        authorId: head.author_id,
        message: 'Follow-up review commit',
        tree: readTree(head.tree_json),
        parentId: head.id,
      });

      const detail = await bob.get(LAB_PULL(number));
      expect(detail.body.reviews[0].stale).toBe(true);
      expect(detail.body.merge).toMatchObject({ approval: { satisfied: false } });
      expect(detail.body.merge.reasons.map((reason) => reason.code)).toContain('approval_required');
    });
  });

  it('rejects an invalid decision without persisting one', async () => {
    await withServer(async (server) => {
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      const before = countRows(server.db, 'reviews');
      const response = await bob.post(`${ACME_PULL(1)}/reviews`, { decision: 'maybe' });
      expect(response.status).toBe(422);
      expect(response.body.error.message).toBe(messages.REVIEW_DECISION_INVALID);
      expect(countRows(server.db, 'reviews')).toBe(before);
    });
  });
});

describe('reviewer requests (REQ-6-4)', () => {
  it('letting the author request and remove an eligible collaborator without creating a review', async () => {
    await withServer(async (server) => {
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      const reviewsBefore = countRows(server.db, 'reviews');

      const requested = await alice.post(`${ACME_PULL(1)}/reviewers`, { username: 'pw-maintain' });
      expect(requested.status).toBe(201);
      expect(requested.body.reviewers.map((reviewer) => reviewer.username)).toEqual(['pw-maintain']);
      expect(requested.body.reviewers[0].requestedBy).toBe('alice-dev');
      // Requesting is idempotent and never produces an approval or comment.
      expect((await alice.post(`${ACME_PULL(1)}/reviewers`, { username: 'pw-maintain' })).body.reviewers).toHaveLength(1);
      expect(countRows(server.db, 'reviews')).toBe(reviewsBefore);

      const reloaded = await alice.get(ACME_PULL(1));
      expect(reloaded.body.reviewers.map((reviewer) => reviewer.username)).toEqual(['pw-maintain']);

      const removed = await alice.delete(`${ACME_PULL(1)}/reviewers/pw-maintain`);
      expect(removed.status).toBe(200);
      expect(removed.body.reviewers).toEqual([]);
      expect((await alice.get(ACME_PULL(1))).body.reviewers).toEqual([]);
    });
  });

  it('removing a request keeps the reviews that reviewer already submitted', async () => {
    await withServer(async (server) => {
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.review).number;
      await alice.post(`${LAB_PULL(number)}/reviewers`, { username: 'bob-reviewer' });

      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'request_changes', summary: 'Needs work' });

      await alice.delete(`${LAB_PULL(number)}/reviewers/bob-reviewer`);
      const detail = await alice.get(LAB_PULL(number));
      expect(detail.body.reviewers).toEqual([]);
      expect(detail.body.reviews).toHaveLength(1);
      expect(detail.body.merge).toMatchObject({ changesRequested: true });
    });
  });

  it('rejects ineligible candidates and unauthorized operators', async () => {
    await withServer(async (server) => {
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      for (const username of ['dave-reader', 'alice-dev', 'nobody-here']) {
        const response = await alice.post(`${ACME_PULL(1)}/reviewers`, { username });
        expect(response.status).toBe(422);
        expect(response.body.error.message).toBe(messages.REVIEWER_NOT_ELIGIBLE);
      }
      expect(countRows(server.db, 'pull_request_reviewers')).toBe(0);

      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      expect((await bob.post(`${ACME_PULL(1)}/reviewers`, { username: 'pw-maintain' })).status).toBe(403);

      const visitor = createClient(server.baseUrl);
      expect((await visitor.post(`${ACME_PULL(1)}/reviewers`, { username: 'pw-maintain' })).status).toBe(401);
    });
  });
});

describe('merge gating and transactional merge (REQ-6-5)', () => {
  it('exposes the gate snapshot and merges the eligible PR in one transaction', async () => {
    await withServer(async (server) => {
      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.eligible).number;

      const detail = await maintain.get(LAB_PULL(number));
      expect(detail.body.merge).toMatchObject({
        eligible: true,
        protected: true,
        requireApproval: true,
        requireCheckTest: true,
        approval: { satisfied: true, count: 1, reviewers: ['bob-reviewer'] },
        check: { satisfied: true, status: 'success' },
        conflicts: false,
        changesRequested: false,
        reasons: [],
      });

      const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
      const mainBefore = branchByName(server.db, repo.id, 'main').head_commit_id;

      const merged = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(merged.status).toBe(200);
      expect(merged.body.pull).toMatchObject({ state: 'merged' });
      expect(merged.body.pull.mergedCommitId).toBeTruthy();
      expect(merged.body.merged).toMatchObject({
        commitId: merged.body.pull.mergedCommitId,
        merger: 'pw-maintain',
      });
      expect(merged.body.activities.map((activity) => activity.kind)).toContain('pull_request_merged');

      const pull = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.eligible);
      const mainAfter = branchByName(server.db, repo.id, 'main').head_commit_id;
      expect(mainAfter).toBe(pull.merged_commit_id);
      expect(mainAfter).not.toBe(mainBefore);

      // The merge commit has both parents and a consistent first-parent change set.
      const parents = server.db
        .prepare('SELECT parent_commit_id, position FROM commit_parents WHERE commit_id = ? ORDER BY position')
        .all(mainAfter);
      expect(parents).toEqual([
        { parent_commit_id: mainBefore, position: 0 },
        { parent_commit_id: pull.compare_commit_id, position: 1 },
      ]);
      const mergeCommit = commitById(server.db, mainAfter);
      expect(commitById(server.db, mainAfter).parent_id).toBe(mainBefore);
      expect(mergeCommit.message).toBe(
        `Merge pull request #${number} from ${SEED_MERGE_LAB_BRANCHES.eligible}`,
      );
      const stored = server.db
        .prepare('SELECT path, status, additions, deletions FROM commit_files WHERE commit_id = ? ORDER BY path')
        .all(mainAfter);
      const computed = diffTrees(readTree(commitById(server.db, mainBefore).tree_json), readTree(mergeCommit.tree_json))
        .map(({ path, status, additions, deletions }) => ({ path, status, additions, deletions }))
        .sort((a, b) => (a.path < b.path ? -1 : 1));
      expect(stored).toEqual(computed);

      // The compare branch is untouched.
      expect(branchByName(server.db, repo.id, SEED_MERGE_LAB_BRANCHES.eligible).head_commit_id).toBe(
        pull.compare_commit_id,
      );

      // Merged is terminal.
      expect((await maintain.post(`${LAB_PULL(number)}/merge`)).status).toBe(422);
      expect((await maintain.post(`${LAB_PULL(number)}/close`)).status).toBe(422);
      expect((await maintain.post(`${LAB_PULL(number)}/reopen`)).status).toBe(422);
      expect((await maintain.get(LAB_PULL(number))).body.pull.state).toBe('merged');
    });
  });

  it('refuses a merge without the required approval and leaves everything unchanged', async () => {
    await withServer(async (server) => {
      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.blocked).number;
      const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
      const before = {
        head: branchByName(server.db, repo.id, 'main').head_commit_id,
        commits: countRows(server.db, 'commits'),
        parents: countRows(server.db, 'commit_parents'),
      };

      const detail = await maintain.get(LAB_PULL(number));
      expect(detail.body.merge.reasons.map((reason) => reason.message)).toContain(
        messages.REVIEW_REQUIRED_BY_BRANCH_PROTECTION,
      );

      const rejected = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(rejected.status).toBe(422);
      expect(rejected.body.error.message).toBe(messages.REVIEW_REQUIRED_BY_BRANCH_PROTECTION);
      expect(branchByName(server.db, repo.id, 'main').head_commit_id).toBe(before.head);
      expect(countRows(server.db, 'commits')).toBe(before.commits);
      expect(countRows(server.db, 'commit_parents')).toBe(before.parents);
      expect(pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.blocked).state).toBe('open');
    });
  });

  it('refuses when the required check is not successful', async () => {
    await withServer(async (server) => {
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.review).number;
      const bob = createClient(server.baseUrl);
      await signInAs(bob, 'bob-reviewer');
      await bob.post(`${LAB_PULL(number)}/reviews`, { decision: 'approve', summary: '' });

      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      const detail = await maintain.get(LAB_PULL(number));
      expect(detail.body.merge.requireCheckTest).toBe(true);
      expect(detail.body.merge.check).toMatchObject({ satisfied: false, status: 'pending' });
      const rejected = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(rejected.status).toBe(422);
      expect(rejected.body.error.message).toBe(messages.PULL_MERGE_CHECK_REQUIRED);
    });
  });

  it('refuses conflicting changes and closed PRs', async () => {
    await withServer(async (server) => {
      const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.blocked).number;
      const main = branchByName(server.db, repo.id, 'main');
      const mainHead = commitById(server.db, main.head_commit_id);
      // Change the same path on the base side: both sides changed it differently.
      pushCommit(server.db, {
        repo,
        branch: main,
        authorId: mainHead.author_id,
        message: 'Conflicting policy change',
        tree: { ...readTree(mainHead.tree_json), 'docs/blocked.md': '# Blocked from main\n' },
        parentId: mainHead.id,
      });

      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      const detail = await maintain.get(LAB_PULL(number));
      expect(detail.body.merge).toMatchObject({ conflicts: true, eligible: false });
      const rejected = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(rejected.status).toBe(422);
      expect(rejected.body.error.message).toBe(messages.PULL_MERGE_CONFLICTS);

      // A closed PR is never mergeable.
      await maintain.post(`${LAB_PULL(number)}/close`);
      const closedMerge = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(closedMerge.status).toBe(422);
      expect(closedMerge.body.error.message).toBe(messages.PULL_NOT_OPEN);
    });
  });

  it('refuses a PR whose compare head is already part of the base branch', async () => {
    await withServer(async (server) => {
      const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.blocked).number;
      const main = branchByName(server.db, repo.id, 'main');
      // Point the compare branch at the base head: there is nothing left to merge.
      server.db
        .prepare('UPDATE branches SET head_commit_id = ? WHERE id = ?')
        .run(main.head_commit_id, branchByName(server.db, repo.id, SEED_MERGE_LAB_BRANCHES.blocked).id);

      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      const detail = await maintain.get(LAB_PULL(number));
      expect(detail.body.merge).toMatchObject({ noChanges: true, eligible: false });
      const rejected = await maintain.post(`${LAB_PULL(number)}/merge`);
      expect(rejected.status).toBe(422);
      expect(rejected.body.error.message).toBe(messages.PULL_MERGE_NO_CHANGES);
    });
  });

  it('lets a maintainer merge an unprotected PR without approval or check requirements', async () => {
    await withServer(async (server) => {
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      const number = pullByTitle(server.db, 'protection-lab', 'Update policy documentation').number;
      const response = await alice.post(`/api/repos/alice-dev/protection-lab/pulls/${number}/merge`);
      expect(response.status).toBe(200);
      expect(response.body.pull.state).toBe('merged');
      expect(response.body.merge).toMatchObject({ eligible: false, reasons: [{ code: 'not_open' }] });
    });
  });

  it('restricts merging to Maintain and above', async () => {
    await withServer(async (server) => {
      const number = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.blocked).number;
      for (const [username, status] of [
        ['bob-reviewer', 403],
        ['dave-reader', 403],
      ]) {
        const client = createClient(server.baseUrl);
        await signInAs(client, username);
        expect((await client.post(`${LAB_PULL(number)}/merge`)).status).toBe(status);
      }
      const visitor = createClient(server.baseUrl);
      expect((await visitor.post(`${LAB_PULL(number)}/merge`)).status).toBe(401);
    });
  });
});

describe('close and reopen (REQ-6-6)', () => {
  it('lets the author close and reopen without touching any branch or review', async () => {
    await withServer(async (server) => {
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      const pull = pullByTitle(server.db, SEED_PUBLIC_REPO.name, 'Improve onboarding');
      const repo = repoByName(server.db, SEED_PUBLIC_REPO.name);
      const headBefore = branchByName(server.db, repo.id, 'pr-onboarding').head_commit_id;

      const closed = await alice.post(`${ACME_PULL(pull.number)}/close`);
      expect(closed.status).toBe(200);
      expect(closed.body.pull.state).toBe('closed');
      expect(closed.body.activities.map((activity) => activity.kind)).toContain('pull_request_closed');
      expect(branchByName(server.db, repo.id, 'pr-onboarding').head_commit_id).toBe(headBefore);

      const reopened = await alice.post(`${ACME_PULL(pull.number)}/reopen`);
      expect(reopened.status).toBe(200);
      expect(reopened.body.pull.state).toBe('open');
      expect(reopened.body.activities.map((activity) => activity.kind)).toContain('pull_request_reopened');
      // Discussion and diff survive the status changes.
      expect(reopened.body.comments).toHaveLength(1);
    });
  });

  it('hides the operations from Read, Triage and Write (403) and rejects Merged PRs', async () => {
    await withServer(async (server) => {
      const pull = pullByTitle(server.db, SEED_PUBLIC_REPO.name, 'Fix search');
      for (const username of ['dave-reader', 'pw-triage', 'bob-reviewer']) {
        const client = createClient(server.baseUrl);
        await signInAs(client, username);
        expect((await client.post(`${ACME_PULL(pull.number)}/close`)).status).toBe(403);
      }
      const visitor = createClient(server.baseUrl);
      expect((await visitor.post(`${ACME_PULL(pull.number)}/close`)).status).toBe(401);

      // The maintain account may close another author's PR (REQ-6-6 role set).
      const maintain = createClient(server.baseUrl);
      await signInAs(maintain, 'pw-maintain');
      expect((await maintain.post(`${ACME_PULL(pull.number)}/close`)).status).toBe(200);
      expect((await maintain.post(`${ACME_PULL(pull.number)}/reopen`)).status).toBe(200);

      // Merged stays terminal for close and reopen.
      const alice = createClient(server.baseUrl);
      await signInAs(alice, 'alice-dev');
      const mergeLabNumber = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.eligible).number;
      await maintain.post(`${LAB_PULL(mergeLabNumber)}/merge`);
      const mergedClose = await maintain.post(`${LAB_PULL(mergeLabNumber)}/close`);
      expect(mergedClose.status).toBe(422);
      expect(mergedClose.body.error.message).toBe(messages.PULL_MERGED_TERMINAL);
      expect((await maintain.post(`${LAB_PULL(mergeLabNumber)}/reopen`)).status).toBe(422);
    });
  });
});

describe('M6b seed (docs/seed-data.md)', () => {
  it('exposes the merge-lab PRs and is idempotent', async () => {
    await withServer(async (server) => {
      const visitor = createClient(server.baseUrl);
      const list = await visitor.get(`${LAB}/pulls`);
      expect(list.status).toBe(200);
      expect(list.body.pulls.map((pull) => pull.title)).toEqual([
        SEED_MERGE_LAB_TITLES.review,
        SEED_MERGE_LAB_TITLES.blocked,
        SEED_MERGE_LAB_TITLES.eligible,
      ]);

      const eligible = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.eligible);
      expect(eligible.state).toBe('open');
      const rule = server.db
        .prepare('SELECT * FROM branch_protections WHERE repo_id = ? AND branch_name = ?')
        .get(eligible.repo_id, 'main');
      expect(rule).toMatchObject({ require_approval: 1, require_check_test: 1 });

      const before = {
        pulls: countRows(server.db, 'pull_requests'),
        reviews: countRows(server.db, 'reviews'),
        checks: countRows(server.db, 'check_runs'),
        branches: countRows(server.db, 'branches'),
        commits: countRows(server.db, 'commits'),
      };
      runSeeds(server.db, { logger: { error: () => {} } });
      expect({
        pulls: countRows(server.db, 'pull_requests'),
        reviews: countRows(server.db, 'reviews'),
        checks: countRows(server.db, 'check_runs'),
        branches: countRows(server.db, 'branches'),
        commits: countRows(server.db, 'commits'),
      }).toEqual(before);
    });
  });
});

